"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[3581],{63581:a=>{a.exports=JSON.parse('{"slug":"inflyaciya-oktyabr-2026-tarify-zhkh","locale":"zh","title":"公用事业调价后一周，年通胀从6.26%升至7.17%","description":"2026年九月29日至十月5日物价上涨0.96%，年通胀7.17%。公用事业贡献多少，为何年指标一周跳升。","blocks":[{"id":"b001","kind":"paragraph","text":"2026年九月29日至十月5日，俄罗斯消费价格涨0.96%，此前一周0.12%。十月1日公用事业调价贡献其中0.75个百分点。排污涨17.1%，冷水15.3%，热水14.2%，供暖12.7%，电力12%。总公用事业账单调整较小，全国均值9.9%，因为政府为账单总额而非每项服务设限。莫斯科最高15%，圣彼得堡14.6%，最高的斯塔夫罗波尔边疆区22%。"},{"id":"b002","kind":"paragraph","text":"剔除公用事业，一周涨0.21%，比此前整篮子涨幅还快。食品涨0.17%：果蔬跌0.57%，其余涨0.24%。鸡蛋涨2.2%，肉类罐头1.6%，荞麦1%。非食品涨0.13%，智能手机1.1%，电视1%。"},{"id":"b003","kind":"paragraph","text":"年通胀一周由6.26%升至7.17%。设想家庭去年七月、今年十月才交全年车险，十月同比支出看似增加，但全年总额相同。公用事业类似：2025年七月1日上调11.9%；2026年一月1.7%、十月9.9%，合计约11.8%。2025年十月没有调价，故本次跳升全部进入同比，这称基数效应。2027年起调价日又回七月。"},{"id":"b004","kind":"paragraph","text":"若账单公用事业费每月6千卢布，平均约多600卢布，莫斯科最多900。房屋维护和大修费不在本次调整内，这项支出无法推迟。存款暂仍跑赢物价：九月末10大银行平均最高利率13.05%，年通胀7.17%。"},{"id":"b005","kind":"paragraph","text":"央行预计2026年通胀6–7%。年初以来已涨5.94%，按监管机构方法计算的同比7.08%已超过年末预测上沿。央行主席顾问基里尔\xb7特列马索夫九月已提过调价贡献约0.7个百分点，故十月23日决定更看其他价格。若每周0.21%持续全年，将超过11%。九月11日央行维持14%，并警告通胀加速风险占优。"},{"id":"b006","kind":"paragraph","text":"单周证明有限。Rosstat十月9日发布九月月度数据，十月14日发布下一周数据。若不含公用事业的涨幅回到每周0.1%，此次跳升可视为一次性；若保持约0.2%，央行更缺乏降息理由，贷款昂贵更久，存款收益也更久。"},{"id":"b007","kind":"heading","text":"2026年十月初为何单周通胀达到0.96%？"},{"id":"b008","kind":"paragraph","text":"十月1日公用事业平均调价9.9%，贡献0.96%中的0.75个百分点。剔除后，价格一周涨0.21%。"},{"id":"b009","kind":"heading","text":"年通胀为何一周从6.26%升至7.17%？"},{"id":"b010","kind":"paragraph","text":"基数效应。2025年七月1日公用事业涨11.9%；2026年一月涨1.7%，十月1日起涨9.9%。2025年十月未调价，因此同比突然跳升，尽管全年涨幅仍近似，约11.8%。"},{"id":"b011","kind":"heading","text":"2026年十月1日起公用事业账单涨多少？"},{"id":"b012","kind":"paragraph","text":"全国均值9.9%，莫斯科最高15%，圣彼得堡14.6%，斯塔夫罗波尔22%。不含房屋维护和大修。单项周涨幅为排污17.1%、冷水15.3%、供暖12.7%、电力12%。"}],"sources":[{"label":"俄罗斯九月29日至十月5日通胀数据","url":"https://www.vedomosti.ru/economics/news/2026/10/07/1235202-inflyatsiya-v-rossii"},{"label":"经济发展部估计公用事业调价贡献单周通胀0.75个百分点","url":"https://www.vedomosti.ru/economics/news/2026/10/07/1235205-minek-otsenil-vklad-indeksatsii"},{"label":"公用事业调价对周通胀贡献估为0.75个百分点","url":"https://www.interfax.ru/business/1120937"},{"label":"经济发展部：九月29日至十月5日俄罗斯年通胀7.17%","url":"https://www.bfm.ru/news/620178"},{"label":"2026年十月1日公用事业收费及账单变化","url":"https://finuslugi.ru/navigator/kak-ehto-rabotaet/stat_tarify-zhkkh-s-1-oktyabrya-2026-goda-kak-izmenyatsya-platezhi"},{"label":"公用事业调整使俄罗斯周通胀跳升0.96%","url":"https://ru.themoscowtimes.com/2026/10/07/nedelnaya-inflyatsiya-v-rf-podskochila-na-096-iz-za-indeksatsii-tarifov-a208051"},{"label":"央行上调2026年通胀预测","url":"https://www.kommersant.ru/doc/8843971"},{"label":"2026年九月11日关键利率维持14%","url":"https://finance.mail.ru/article/stavka-centrobanka-neizmenna-14-kak-reshenie-soveta-direktorov-cb-povliyaet-na-ekonomiku-69227357/"},{"label":"十大银行平均最高存款利率升至13.05%","url":"https://ria.ru/20261001/bank-2121443529.html"}],"sourceBodySha256":"2123f3266d3346c5a40c0ca0051d02fcbfdc4a0c1b55fe5c397edea22f975b4d"}')}}]);